static decimal Price(Order o, int qty)
{
    decimal basePrice = o.Base();
    decimal discount = 0m;
    decimal Secondary() => basePrice * qty;
    void ApplyDiscount() { if (qty > 100) discount = 0.05m; }
    decimal Compute() { ApplyDiscount(); return Secondary() * (1 - discount); }
    return Compute();
}
